  cursor: pointer;
  transition: background-color 0.2s;
}

.option:hover {
  background-color: #f0f7ff;
}

.option input {
  margin-right: 0.75rem;
  width: 1.25rem;
  height: 1.25rem;
  cursor: pointer;
}

.option label {
  cursor: pointer;
  flex: 1;
}

.submit-btn {
  background-color: var(--primary-color);
  color: white;
  border: none;
  padding: 0.75rem 1.5rem;
  font-size: 1rem;
  font-weight: 600;
  border-radius: 4px;
  cursor: pointer;
  width: 100%;
  transition: background-color 0.2s;
}

.submit-btn:hover {
  background-color: #0052a3;
}

.submit-btn:focus-visible {
  outline: 3px solid var(--focus-ring);
  outline-offset: 2px;
}

.results {
  margin-top: 2rem;
  padding: 1rem;
  border-radius: 4px;
  border: 1px solid var(--border-color);
}

.results h2 {
  margin-top: 0;
}

.correct {
  color: var(--success-color);
  font-weight: bold;
}

.incorrect {
  color: var(--error-color);
  font-weight: bold;
}

