    execSync('npx playwright install chromium >/dev/null 2>&1');
    browser = await chromium.launch();
  }
  const page = await browser.newPage();

  // Load the page
  const htmlPath = path.resolve('index.html');
  const htmlContent = fs.readFileSync(htmlPath, 'utf8');
  await page.setContent(htmlContent, { waitUntil: 'load' });

  // Inject CSS and JS if they exist
  if (fs.existsSync('styles.css')) {
    const cssContent = fs.readFileSync('styles.css', 'utf8');
    await page.addStyleTag({ content: cssContent });
  }
  if (fs.existsSync('script.js')) {
    const jsContent = fs.readFileSync('script.js', 'utf8');
    await page.addScriptTag({ content: jsContent });
  }

  // Inject axe-core
  await page.addScriptTag({ path: '/tmp/axe.min.js' });

  // Run axe
  const results = await page.evaluate(async () => {
    return await window.axe.run();
  });

  const wcag = results.violations.filter(v => !v.tags.includes('best-practice'));
  const bp = results.violations.filter(v => v.tags.includes('best-practice'));

  console.log(JSON.stringify({
    wcag: wcag.map(v => ({ id: v.id, impact: v.impact, help: v.help, nodes: v.nodes.map(n => n.target) })),
    bp: bp.map(v => ({ id: v.id, help: v.help, nodes: v.nodes.map(n => n.target) }))
  }, null, 2));

  await browser.close();
  process.exit(wcag.length > 0 ? 1 : 0);
})();

