', direction=None, fact=None, file_name='/workspace/sandbox/skills/building-accessible-ui/checkbox-group--framework-react--style-modern/google/gemini-3-flash-preview__s1/script.js', full_command_text=None, has_write_file_redirection=None, hook_message=None, intention='Edit file', new_file_contents='const questions = [
  {
    id: 'q1',
    text: 'Which of the following are statically typed languages?',
    help: 'Statically typed languages perform type checking at compile-time.',
    options: [
      { id: 'q1-o1', text: 'Java', correct: true },
      { id: 'q1-o2', text: 'C++', correct: true },
      { id: 'q1-o3', text: 'Python', correct: false },
      { id: 'q1-o4', text: 'JavaScript', correct: false }
    ]
  },
  {
    id: 'q2',
    text: 'Which of these languages are primarily used for systems programming?',
    options: [
      { id: 'q2-o1', text: 'Rust', correct: true },
      { id: 'q2-o2', text: 'C', correct: true },
      { id: 'q2-o3', text: 'SQL', correct: false },
      { id: 'q2-o4', text: 'PHP', correct: false }
    ]
  },
  {
    id: 'q3',
    text: 'Which languages are considered multi-paradigm?',
    options: [
      { id: 'q3-o1', text: 'Python', correct: true },
      { id: 'q3-o2', text: 'JavaScript', correct: true },
      { id: 'q3-o3', text: 'C++', correct: true },
      { id: 'q3-o4', text: 'Haskell', correct: false }
    ]
  }
];

function renderQuiz() {
  const form = document.getElementById('quiz-form');
  const questionsContainer = document.getElementById('questions-container');

  questions.forEach((q, qIndex) => {
    const fieldDiv = document.createElement('div');
    fieldDiv.className = 'form-field';

    const fieldset = document.createElement('fieldset');
    const helpId = q.help ? `${q.id}-help` : null;
    if (helpId) {
      fieldset.setAttribute('aria-describedby', helpId);
    }

    const legend = document.createElement('legend');
    legend.textContent = q.text;
    fieldset.appendChild(legend);

    if (q.help) {
      const helpP = document.createElement('p');
      helpP.id = helpId;
      helpP.className = 'help-text';
      helpP.textContent = q.help;
      fieldset.appendChild(helpP);
    }

    q.options.forEach(opt => {
      const optionDiv = document.createElement('div');
      optionDiv.className = 'option';

      const input = document.createElement('input');
      input.type = 'checkbox';
      input.id = opt.id;
      input.name = q.id;
      input.value = opt.id;

      const label = document.createElement('label');
      label.setAttribute('for', opt.id);
      label.textContent = opt.text;

      optionDiv.appendChild(input);
      optionDiv.appendChild(label);
      fieldset.appendChild(optionDiv);
    });

    fieldDiv.appendChild(fieldset);
    questionsContainer.appendChild(fieldDiv);
  });
}

function handleSubmit(event) {
  event.preventDefault();
  const formData = new FormData(event.target);
  const resultsContainer = document.getElementById('results');
  resultsContainer.innerHTML = '<h2>Quiz Results</h2>';
  resultsContainer.hidden = false;

  let score = 0;

  questions.forEach(q => {
    const selectedOptions = formData.getAll(q.id);
    const correctOptions = q.options.filter(opt => opt.correct).map(opt => opt.id);

    const isCorrect = 
      selectedOptions.length === correctOptions.length && 
      selectedOptions.every(val => correctOptions.includes(val));

    const resultP = document.createElement('div');
    resultP.setAttribute('role', 'group');
    resultP.style.marginBottom = '1rem';
    if (isCorrect) {
      score++;
      resultP.innerHTML = `<p><span class="correct">Correct!</span> ${q.text}</p>`;
    } else {
      resultP.innerHTML = `<p><span class="incorrect">Incorrect.</span> ${q.text}</p>
                           <p style="font-size: 0.9rem; margin-top: -0.5rem;">Correct answers: ${q.options.filter(o => o.correct).map(o => o.text).join(', ')}</p>`;
    }
    resultsContainer.appendChild(resultP);
  });

  const finalScore = document.createElement('p');
  finalScore.style.fontWeight = 'bold';
  finalScore.textContent = `Total Score: ${score} / ${questions.length}`;
  resultsContainer.appendChild(finalScore);

  // Announcement for screen readers
  const status = document.getElementById('status-message');
  status.textContent = `Quiz submitted. You scored ${score} out of ${questions.length}.`;

  // Focus results
  resultsContainer.setAttribute('tabindex', '-1');
  resultsContainer.focus();
}

document.addEventListener('DOMContentLoaded', () => {
  renderQuiz();
  document.getElementById('quiz-form').addEventListener('submit', handleSubmit);
});
