  const formData = new FormData(event.target);
  const resultsContainer = document.getElementById('results');
  resultsContainer.innerHTML = '<h2>Quiz Results</h2>';
  resultsContainer.hidden = false;

  let score = 0;

  questions.forEach(q => {
    const selectedOptions = formData.getAll(q.id);
    const correctOptions = q.options.filter(opt => opt.correct).map(opt => opt.id);

    const isCorrect = 
      selectedOptions.length === correctOptions.length && 
      selectedOptions.every(val => correctOptions.includes(val));

    const resultP = document.createElement('div');
    resultP.setAttribute('role', 'group');
    resultP.style.marginBottom = '1rem';
    if (isCorrect) {
      score++;
      resultP.innerHTML = `<p><span class="correct">Correct!</span> ${q.text}</p>`;
    } else {
      resultP.innerHTML = `<p><span class="incorrect">Incorrect.</span> ${q.text}</p>
                           <p style="font-size: 0.9rem; margin-top: -0.5rem;">Correct answers: ${q.options.filter(o => o.correct).map(o => o.text).join(', ')}</p>`;
    }
    resultsContainer.appendChild(resultP);
  });

  const finalScore = document.createElement('p');
  finalScore.style.fontWeight = 'bold';
  finalScore.textContent = `Total Score: ${score} / ${questions.length}`;
  resultsContainer.appendChild(finalScore);

  // Announcement for screen readers
  const status = document.getElementById('status-message');
  status.textContent = `Quiz submitted. You scored ${score} out of ${questions.length}.`;

  // Focus results
  resultsContainer.setAttribute('tabindex', '-1');
  resultsContainer.focus();
}

document.addEventListener('DOMContentLoaded', () => {
  renderQuiz();
  document.getElementById('quiz-form').addEventListener('submit', handleSubmit);
});
